function toTraditional(value: string) {
  const phrased = traditionalPhrases.reduce((result, [from, to]) => result.replaceAll(from, to), value);
  return [...phrased].map(char => traditionalCharacters[char] || char).join("");
}

export function uiText(locale: Locale, zh: string, en: string, traditionalText?: string) {
  if (locale === "zh-CN") return zh;
  if (locale === "zh-TW") return traditionalText || toTraditional(zh);
  if (locale === "en") return en;
  return ui[en]?.[locale] || en;
}
